    // Alimenter la datalist pour l'autocomplétion
    (function initDatalist() {
      const dl = document.getElementById('mat-list');
      if (!dl) return;
      TOUS_MATRICULES.forEach(m => {
        const opt = document.createElement('option');
        opt.value = m;
        const emp = EMPLOYES[m];
        if (emp) opt.label = emp.nom + ' ' + emp.prenoms;
        dl.appendChild(opt);
      });
    })();

    

    async function autoFillFromMatricule(val) {
  const mat = val.trim();
  const badge = document.getElementById('lookup-badge');

  if (!mat) {
    clearEmployeeFields();
    if (badge) badge.style.display = 'none';
    return;
  }

  try {
    const response = await fetch(`api/employe_get.php?matricule=${encodeURIComponent(mat)}`);
    const json = await response.json();

    if (!json.success) {
      clearEmployeeFields();

      if (badge) {
        badge.textContent = '✗ Matricule introuvable dans la base';
        badge.style.display = 'flex';
        badge.className = 'lookup-badge notfound';
      }
      return;
    }

    const emp = json.data;

    setField('inp-employe-id', emp.id);
    setField('inp-fonction-id', emp.id_fonction);
    setField('inp-manager-id', emp.manager_id || '');

    setField('inp-collab-nom', emp.nom_complet);
    setField('inp-date-embauche', emp.date_embauche);
    setField('inp-lieu', emp.lieu);
    setField('inp-fonction', emp.fonction);
    setField('inp-anciennete', emp.anciennete);

    const managerNomInput = document.querySelector('[name="manager_nom"]');
    const managerFonctionInput = document.querySelector('[name="manager_fonction"]');

    if (managerNomInput) managerNomInput.value = emp.manager_nom_complet || '';
    if (managerFonctionInput) managerFonctionInput.value = emp.manager_fonction || '';

    const missionsEl = document.querySelector('[name="missions_principales"]');
    if (missionsEl && !missionsEl.value) {
      missionsEl.value = emp.missions || '';
    }

    const sigC = document.getElementById('sig_collab_auto');
    const sigCn = document.querySelector('[name="sig_collab_nom"]');
    if (sigC) sigC.value = emp.nom_complet;
    if (sigCn) sigCn.value = emp.nom_complet;

    const sigM = document.getElementById('sig_manager_auto');
    const sigMn = document.querySelector('[name="sig_manager_nom"]');
    if (sigM) sigM.value = emp.manager_nom_complet || '';
    if (sigMn) sigMn.value = emp.manager_nom_complet || '';

    if (badge) {
      badge.textContent = `✓ ${emp.nom_complet} — ${emp.fonction} (${emp.lieu})`;
      badge.style.display = 'flex';
      badge.className = 'lookup-badge found';
    }

  } catch (error) {
    console.error(error);

    if (badge) {
      badge.textContent = '✗ Erreur serveur lors du chargement';
      badge.style.display = 'flex';
      badge.className = 'lookup-badge notfound';
    }
  }
}

function clearEmployeeFields() {
  [
    'inp-employe-id',
    'inp-fonction-id',
    'inp-manager-id',
    'inp-collab-nom',
    'inp-date-embauche',
    'inp-lieu',
    'inp-fonction',
    'inp-anciennete'
  ].forEach(id => setField(id, ''));

  const managerNomInput = document.querySelector('[name="manager_nom"]');
  const managerFonctionInput = document.querySelector('[name="manager_fonction"]');
  const missionsEl = document.querySelector('[name="missions_principales"]');

  if (managerNomInput) managerNomInput.value = '';
  if (managerFonctionInput) managerFonctionInput.value = '';
  if (missionsEl) missionsEl.value = '';

  const sigC = document.getElementById('sig_collab_auto');
  const sigCn = document.querySelector('[name="sig_collab_nom"]');
  const sigM = document.getElementById('sig_manager_auto');
  const sigMn = document.querySelector('[name="sig_manager_nom"]');

  if (sigC) sigC.value = '';
  if (sigCn) sigCn.value = '';
  if (sigM) sigM.value = '';
  if (sigMn) sigMn.value = '';
}

function setField(id, value) {
  const el = document.getElementById(id);
  if (el) el.value = value ?? '';
}


    // Auto-fill signatures from header fields
    document.querySelector('[id="inp-collab-nom" name="collab_nom"]').addEventListener('input', function () {
      document.getElementById('sig_collab_auto').value = this.value;
      document.querySelector('[name="sig_collab_nom"]').value = this.value;
    });
    document.querySelector('[name="manager_nom"]').addEventListener('input', function () {
      document.getElementById('sig_manager_auto').value = this.value;
      document.querySelector('[name="sig_manager_nom"]').value = this.value;
    });

    // Update score bar
    function updateBar(input, barId) {
      const val = parseFloat(input.value) || 0;
      const pct = Math.min(Math.max(val / 5 * 100, 0), 100);
      document.getElementById(barId).style.width = pct + '%';
      computeAverage();
    }

    // Compute average note
    function computeAverage() {
      const notes = [];
      for (let i = 1; i <= 6; i++) {
        const inp = document.querySelector(`[name="perf_${i}_note"]`);
        const v = parseFloat(inp?.value);
        if (!isNaN(v)) notes.push(Math.min(5, Math.max(1, v)));
      }
      const avg = notes.length ? (notes.reduce((a, b) => a + b, 0) / notes.length).toFixed(2) : '—';
      document.getElementById('note-moy').textContent = avg;
      document.getElementById('summary-note').textContent = avg;
    }

    // Sync niveau d'expertise to summary
    document.querySelectorAll('[name="niveau_expertise"]').forEach(r => {
      r.addEventListener('change', function () {
        document.getElementById('summary-niveau').textContent = this.value;
      });
    });

    // Sync appreciation to summary
    document.querySelectorAll('[name="appreciation"]').forEach(r => {
      r.addEventListener('change', function () {
        document.getElementById('summary-appr').textContent = this.value;
      });
    });

    // Add axe
    let axeCount = 2;
    function addAxe() {
      axeCount++;
      const container = document.getElementById('axes-container');
      const div = document.createElement('div');
      div.className = 'axe-row';
      div.innerHTML = `
      <div><textarea name="axe_${axeCount}" placeholder="Axe de progrès n°${axeCount}…" style="min-height:80px;border:1.5px solid var(--manager-border);background:var(--manager-bg);border-radius:8px;padding:8px 10px;font-family:inherit;font-size:13px;width:100%;resize:vertical;color:var(--text);"></textarea></div>
      <div><textarea name="axe_${axeCount}_moyen" placeholder="Moyens envisagés…" style="min-height:80px;border:1.5px solid var(--manager-border);background:var(--manager-bg);border-radius:8px;padding:8px 10px;font-family:inherit;font-size:13px;width:100%;resize:vertical;color:var(--text);"></textarea></div>
      <div><textarea name="axe_${axeCount}_collab" placeholder="Votre retour…" style="min-height:80px;border:1.5px solid var(--collab-border);background:var(--collab-bg);border-radius:8px;padding:8px 10px;font-family:inherit;font-size:13px;width:100%;resize:vertical;color:var(--text);"></textarea></div>`;
      container.appendChild(div);
    }

    // Add formation
    document.addEventListener('DOMContentLoaded', function () {
      const container = document.getElementById('formations-container');
      const addBtn = document.getElementById('add-formation-btn');

      let formCount = container.querySelectorAll('.formation-item').length;

      function addFormation() {
        formCount++;

        const div = document.createElement('div');
        div.className = 'formation-item';

        div.innerHTML = `
        <div class="formation-head">
          <span class="formation-badge">Formation ${formCount}</span>
        </div>

        <div class="formation-grid">
          <div class="field-group field-wide">
            <label for="form_${formCount}_titre">Intitulé</label>
            <input
              id="form_${formCount}_titre"
              type="text"
              name="form_${formCount}_titre"
              placeholder="Ex. Excel avancé, management d'équipe, sécurité…"
            />
          </div>

          <div class="field-group">
            <label for="form_${formCount}_priorite">Priorité</label>
            <select id="form_${formCount}_priorite" name="form_${formCount}_priorite">
              <option value="">Sélectionner</option>
              <option value="1 - Urgente">1 - Urgente</option>
              <option value="2 - Importante">2 - Importante</option>
              <option value="3 - Souhaitable">3 - Souhaitable</option>
            </select>
          </div>

          <div class="field-group">
            <label for="form_${formCount}_demandeur">Demandeur</label>
            <select id="form_${formCount}_demandeur" name="form_${formCount}_demandeur">
              <option value="">Sélectionner</option>
              <option value="Collaborateur">Collaborateur</option>
              <option value="Manager">Manager</option>
              <option value="Les deux">Les deux</option>
            </select>
          </div>
        </div>
      `;

        container.appendChild(div);
      }

      addBtn.addEventListener('click', addFormation);
    });

    // Reset
    function resetForm() {
      if (confirm('Êtes-vous sûr de vouloir réinitialiser tous les champs ?')) {
        document.getElementById('eaa-form').reset();
        document.getElementById('note-moy').textContent = '—';
        document.getElementById('summary-note').textContent = '—';
        document.getElementById('summary-niveau').textContent = '—';
        document.getElementById('summary-appr').textContent = '—';
        for (let i = 1; i <= 6; i++) {
          const b = document.getElementById('bar_' + i);
          if (b) b.style.width = '0%';
        }
      }
    }

    // Submit
    document.getElementById('eaa-form').addEventListener('submit', function (e) {
      e.preventDefault();
      const nom = document.querySelector('[id="inp-collab-nom" name="collab_nom"]').value;
      if (!nom) { alert('Veuillez renseigner le nom du collaborateur.'); return; }
      alert('✅ Le formulaire EAA de ' + nom + ' a été validé.\n\nVeillez à le transmettre à la DRH selon la procédure en vigueur.');
    });

    // Set current year
    const y = new Date().getFullYear();
    document.getElementById('annee-label').textContent = y;
    document.getElementById('annee-s1').textContent = y;
    document.getElementById('annee-s2').textContent = y;